/* Reference 01 presentation only. Input summaries come from the existing model.
   No DOM access, persistence, device API, network call or inferred nutrition. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.NutriDietReference01=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={
 plate:'<ellipse cx="12" cy="13" rx="8" ry="6"/><ellipse cx="12" cy="13" rx="5" ry="3.5"/><path d="M3 3v4m3-4v4M3 5h3m-1.5 2v14M21 3v18"/>',
 pen:'<path d="m4 16 12-12 4 4L8 20H4v-4Zm10-10 4 4M3 23h18"/>',
 camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3V7Z"/><circle cx="12" cy="14" r="4"/>',
 mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v4m-4 0h8"/>',
 chart:'<path d="M5 22v-9m7 9V7m7 15V2"/>',
 drop:'<path d="M12 2C10 6 4 12 4 16a8 8 0 0 0 16 0c0-4-6-10-8-14Z"/>',
 grain:'<path d="M12 2v21M12 9C5 10 4 5 5 4c4-1 7 5 7 5Zm0 6c7 1 8-4 7-5-4-1-7 5-7 5Zm0 6c-7 1-8-4-7-5 4-1 7 5 7 5Z"/>',
 leaf:'<path d="M4 20C0 8 10 3 22 2c-1 12-7 22-18 18Zm0 0L17 7"/>',
 sun:'<circle cx="12" cy="12" r="5"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',
 cube:'<path d="m12 2 10 6v10l-10 6-10-6V8l10-6Zm0 12 10-6M12 14 2 8m10 6v10"/>',
 info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v7m0-12v1"/>'
};
function icon(name){return '<svg class="r01-icon" viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[name]||icons.info)+'</svg>';}
function value(total,unit){return '<strong>'+esc(total.value??'未知')+'</strong>'+(total.value===null?'':'<span>'+esc(unit)+'</span>');}
function shortDate(date){const m=/^\d{4}-(\d{2})-(\d{2})$/.exec(date);return m?Number(m[1])+'月'+Number(m[2])+'日':date;}
function dateControl(date,id){return `<details class="r01-date-control"><summary>记录日期 · ${esc(date)} <span aria-hidden="true">⌄</span></summary><div class="r01-date-fields"><label for="${id}">查看日期<input id="${id}" type="date" data-date-picker value="${esc(date)}" required></label><button type="button" data-action="today">演示当天</button></div></details>`;}
/* These three existing AI illustrations only decorate exact, untouched seed
   menu records. Edited, arbitrary, mixed or empty slots get a neutral plate.
   The picture never supplies a nutrient value or claims to be a meal photo. */
const seedArt=Object.freeze({
 '燕麦牛奶、鸡蛋':{file:'steamed-egg-custard-ai-v1.webp',label:'鸡蛋菜式示意'},
 '鸡肉糙米饭、清炒蔬菜':{file:'chicken-grain-original.png',label:'鸡肉饭菜式示意'},
 '蔬菜豆腐汤、杂粮饭':{file:'tofu-soup-original.png',label:'豆腐汤菜式示意'}
});
function mealArt(rows){const row=rows.length===1?rows[0]:null,art=row?.source==='synthetic-fixture'&&row.synthetic===true&&Object.prototype.hasOwnProperty.call(seedArt,row.name)?seedArt[row.name]:null;
 return art?`<span class="r01-meal-art"><img src="../assets/recipes/${art.file}" alt="${esc(art.label)}；AI生成配图，不是这餐的照片" width="112" height="112" loading="lazy" decoding="async"><small>AI 菜式示意</small></span>`:`<span class="r01-meal-art r01-neutral-art">${icon('plate')}<small>${rows.length?'无餐食照片':'尚未记录'}</small></span>`;}
function renderDietOverview({date,summary,slots,large}){
 return `<section class="r01-diet-overview" aria-label="合成饮食概览"><header class="r01-heading"><a class="r01-back" href="../nutrition-booklet.html" aria-label="返回营养册">‹</a><div><h1>好好吃饭</h1><p>记录饮食，了解日常</p></div><button type="button" data-action="diet-size" aria-pressed="${large===true}">大字</button></header><div class="r01-utilities">${dateControl(date,'r01-diet-date')}<span class="r01-sound-slot" data-nutri-feedback-slot></span></div><section class="r01-day-card" aria-labelledby="r01-day-title"><div class="r01-day-top"><div><h2 id="r01-day-title">这天饮食</h2><time datetime="${esc(date)}">${esc(shortDate(date))}</time><p>已记录 <b>${esc(summary.count)}</b> 条 · 合成演示</p></div><a class="r01-energy-link" href="intake.html?date=${esc(date)}" aria-label="查看 ${esc(date)} 已记录摄入"><span class="r01-energy">${value(summary.totals.kcal,'kcal')}</span><small>已知小计 · 有值 ${esc(summary.totals.kcal.known)}/${esc(summary.totals.kcal.total)}</small><span class="r01-next" aria-hidden="true">›</span></a></div><nav class="r01-meals" aria-label="查看这天的餐次记录">${slots.map(slot=>`<a href="#hdp-meals-${esc(slot.key)}" class="r01-meal-card">${mealArt(slot.rows)}<b class="r01-meal-label">${esc(slot.label)}</b><span class="r01-meal-energy">${value(slot.summary.totals.kcal,'kcal')}</span><span class="r01-meal-name">${slot.rows.length?esc(slot.rows[0].name):'暂无这餐记录'}</span><small>${esc(slot.rows.length)} 条 · 已知 ${esc(slot.summary.totals.kcal.known)}/${esc(slot.summary.totals.kcal.total)}</small></a>`).join('')}</nav><p class="r01-art-note">配图仅示意菜式，不是餐食照片；数值来自合成记录。</p><details class="r01-macro-details"><summary>三大营养素已知小计 <span aria-hidden="true">⌄</span></summary><div>${[['protein','蛋白质'],['carb','碳水'],['fat','脂肪']].map(([key,label])=>`<span><b>${label}</b> ${summary.totals[key].value===null?'未知':esc(summary.totals[key].value)+' g'}<small>有值 ${esc(summary.totals[key].known)}/${esc(summary.totals[key].total)}</small></span>`).join('')}</div><p>未知不是 0；只汇总已填数值，不是目标或吸收量。</p></details></section><div class="r01-capture-actions"><button class="r01-side-action" type="button" data-action="meal-manual">${icon('pen')}<span>文字记录</span></button><button class="r01-camera" type="button" data-action="meal">${icon('camera')}<strong>拍照记录</strong><small>本机预览 · 手工核对</small></button><button class="r01-side-action" disabled type="button">${icon('mic')}<span>语音未连接</span></button></div><a class="r01-weekly" href="aiAgent.html?view=weekly"><span class="r01-weekly-symbol">${icon('chart')}</span><span><strong>饮食周报</strong><small>回看截至演示当天的 7 天合成记录</small></span><span aria-hidden="true">›</span></a></section>`;
}
function renderIntake({date,summary,water,filter,timelineHtml}){
 const nutrients=[['protein','蛋白质','drop'],['carb','碳水化合物','grain'],['fat','脂肪','drop']];
 return `<section class="r01-intake-view" aria-label="今日合成记录"><header class="r01-intake-heading"><a class="r01-back" href="diet.html?date=${esc(date)}" aria-label="返回这天饮食记录">‹</a><div><h1>今日记录</h1><p>${esc(date)} · 合成演示</p></div><a class="r01-about" href="settings.html" aria-label="数据与服务说明">说明</a></header><div class="r01-utilities">${dateControl(date,'r01-intake-date')}<span class="r01-sound-slot" data-nutri-feedback-slot></span></div><section class="r01-total-card" aria-labelledby="r01-energy-title"><h2 id="r01-energy-title">总能量 <small>已知小计</small></h2><div><span class="r01-total-energy">${value(summary.totals.kcal,'kcal')}</span><p>已记录 <b>${esc(summary.count)}</b> 条<br>有值 ${esc(summary.totals.kcal.known)}/${esc(summary.totals.kcal.total)}</p></div></section><section class="r01-nutrients" aria-label="已记录的三大营养素">${nutrients.map(([key,label,symbol])=>{const t=summary.totals[key];return `<article class="r01-nutrient r01-${key}"><h2>${label}</h2><div class="r01-nutrient-value">${value(t,'g')}</div><progress max="${t.total||1}" value="${t.known}" aria-label="${label}记录数值覆盖 ${t.known}/${t.total}；不是目标达成率"></progress><small>有值 ${esc(t.known)}/${esc(t.total)} 条</small><span class="r01-nutrient-icon">${icon(symbol)}</span></article>`;}).join('')}</section><p class="r01-coverage-note">条形仅表示数值条目覆盖，不是目标达成率；未知不计作 0。</p><section class="r01-more-nutrients" aria-label="未汇总的营养项目">${[['leaf','膳食纤维与糖','当前汇总未提供膳食纤维、糖或添加糖。'],['sun','维生素','当前汇总未提供各类维生素。'],['cube','矿物质','当前汇总未提供各类矿物质。']].map(([symbol,label,note])=>`<details><summary><span class="r01-more-icon">${icon(symbol)}</span><span><strong>${label}</strong><small>本页尚未汇总</small></span><span aria-hidden="true">⌄</span></summary><p>${note}未根据菜名、配图或合成热量推算，不代表实际摄入为零。</p></details>`).join('')}<p class="r01-origin-note">${icon('info')}当前为合成记录，未进行照片识别，不是实际测量。</p></section><section class="r01-water-card"><span class="r01-water-icon">${icon('drop')}</span><div><h2>这天饮水</h2><p><strong>${esc(water)}</strong> ml · 合成记录合计</p></div><button type="button" data-action="water">＋ 记录</button></section><section class="r01-record-tools" aria-label="同一合成记录的操作"><button type="button" data-action="refresh">刷新记录</button><button type="button" data-action="meal">＋ 记一餐</button><a href="aiAgent.html?view=daily">日常自述</a><a href="health-calendar.html?date=${esc(date)}">健康日历</a><a href="aiAgent.html?view=weekly">周报</a><a href="aiAgent.html">AI 助手</a></section><div data-editor></div><section class="r01-timeline"><h2>这天的记录</h2><label>记录类型<select data-filter>${[['all','全部'],['diet','餐食'],['water','饮水'],['health','健康指标'],['self','日常自述']].map(([key,label])=>`<option value="${key}" ${filter===key?'selected':''}>${label}</option>`).join('')}</select></label>${timelineHtml}</section><p data-status role="status" aria-live="polite"></p><p class="hdp-legacy"><a href="intake.html?legacy=1">查看隔离的旧版本机记录</a> · 旧版资料不会混入合成账号</p></section>`;
}
return Object.freeze({buildId:'diet-reference01-v1',renderDietOverview,renderIntake});
});
